package com.khayrul.personalExpenseTracker.ui.screens.manage

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.khayrul.personalExpenseTracker.data.model.Category
import com.khayrul.personalExpenseTracker.data.model.Expense
import com.khayrul.personalExpenseTracker.data.repo.CategoryRepo
import com.khayrul.personalExpenseTracker.data.repo.ExpenseRepo
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class AddExpenseViewModel(
    private val categoryRepo: CategoryRepo,
    private val expenseRepo: ExpenseRepo
): ViewModel() {
    private val _uiState = MutableStateFlow(AddExpenseUiState())
    val uiState = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            categoryRepo.getAllCategories().collect { categories ->
                _uiState.value = _uiState.value.copy(categories = categories)
            }
        }
    }

    fun onAmountChange(amount: Double) {
        _uiState.value = _uiState.value.copy(amount = amount)
    }

    fun onNoteChange(note: String) {
        _uiState.value = _uiState.value.copy(note = note)
    }

    fun onCategoryChange(category: Category) {
        _uiState.value = _uiState.value.copy(category = category)
    }

    fun onDateChange(date: Long) {
        _uiState.value = _uiState.value.copy(date = date)
    }

    fun create() {
        viewModelScope.launch {
            val expense = Expense(
                amount = uiState.value.amount,
                note = uiState.value.note,
                categoryId = uiState.value.category!!.id!!,
                date = uiState.value.date
            )
            expenseRepo.insertExpense(expense)
        }
    }
}

data class AddExpenseUiState(
    val amount: Double = 0.0,
    val note: String = "",
    val category: Category? = null,
    val date: Long = System.currentTimeMillis(),
    val categories: List<Category> = emptyList()
)

package com.khayrul.personalExpenseTracker.ui.screens.manage

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.khayrul.personalExpenseTracker.data.model.Category
import com.khayrul.personalExpenseTracker.data.model.Expense
import com.khayrul.personalExpenseTracker.data.repo.CategoryRepo
import com.khayrul.personalExpenseTracker.data.repo.ExpenseRepo
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class AddExpenseViewModel(
    private val categoryRepo: CategoryRepo,
    private val expenseRepo: ExpenseRepo
): ViewModel() {
    private val _uiState = MutableStateFlow(AddExpenseUiState())
    val uiState = _uiState.asStateFlow()

    init {
        viewModelScope.launch {
            categoryRepo.getAllCategories().collect { categories ->
                _uiState.value = _uiState.value.copy(categories = categories)
            }
        }
    }

    fun onAmountChange(amount: Double) {
        _uiState.value = _uiState.value.copy(amount = amount)
    }

    fun onNoteChange(note: String) {
        _uiState.value = _uiState.value.copy(note = note)
    }

    fun onCategoryChange(category: Category) {
        _uiState.value = _uiState.value.copy(category = category)
    }

    fun onDateChange(date: Long) {
        _uiState.value = _uiState.value.copy(date = date)
    }

    fun create() {
        viewModelScope.launch {
            val expense = Expense(
                amount = uiState.value.amount,
                note = uiState.value.note,
                categoryId = uiState.value.category!!.id!!,
                date = uiState.value.date
            )
            expenseRepo.insertExpense(expense)
        }
    }

    fun createCategory(name: String, color: Int) {
        viewModelScope.launch {
            categoryRepo.insertCategory(Category(name = name, color = color))
        }
    }
}

data class AddExpenseUiState(
    val amount: Double = 0.0,
    val note: String = "",
    val category: Category? = null,
    val date: Long = System.currentTimeMillis(),
    val categories: List<Category> = emptyList()
)
